{"policy":"permit (
    principal is User,
    action == Action::"approveInvoice",
    resource is Invoice
)
when {
    principal.roles.contains(Role::"approver") &&
    resource.submittedAt <= context.currentTime
};

permit (
    principal is User,
    action == Action::"issuePayment",
    resource is Payment
)
when {
    principal.roles.contains(Role::"approver")
};

forbid (
    principal is User,
    action == Action::"approveInvoice",
    resource is Invoice
)
when {
    (principal.roles.contains(Role::"approver") ||
     principal.roles.contains(Role::"financeManager")) &&
    resource.submittedAt > context.currentTime
};

forbid (
    principal is User,
    action == Action::"issuePayment",
    resource is Payment
)
when {
    !context.emergencyDeclared &&
    resource.invoice has approver &&
    resource.invoice.approver == principal
};"}
